// Bundle the validation fixtures into single dependency-free files for minipc (esbuild from tree-r3's node_modules).
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const HERE = path.dirname(fileURLToPath(import.meta.url)), TREE = path.resolve(HERE, '../tree-r3');
const esbuild = createRequire(path.join(TREE, 'package.json'))('esbuild');
fs.mkdirSync(path.join(HERE, 'dist'), { recursive: true });
for (const name of ['fake-runner.mjs', 'fixture-world.mjs']) {
  const out = path.join(HERE, 'dist', name);
  await esbuild.build({ absWorkingDir: HERE, entryPoints: [path.join(HERE, 'src', name)], outfile: out, bundle: true, platform: 'node', format: 'esm', target: 'node22', legalComments: 'none', nodePaths: [path.join(TREE, 'node_modules')],
    banner: { js: `// Generated by winval/build.mjs from src/${name}; synthetic validation fixture.\nimport {createRequire as __winvalCreateRequire} from "node:module"; const require=__winvalCreateRequire(import.meta.url);` } });
  execFileSync(process.execPath, ['--check', out]);
  console.log(name, createHash('sha256').update(fs.readFileSync(out)).digest('hex'), fs.statSync(out).size);
}
